# 写入白话初稿内容
for i in range(len(paras)):
    para_text = paras[i]["text"]
    trans = translations[i]
    notes = notes_list[i]
    note_text = "；".join(notes) if notes else ""
    trans_content += f"### 段落{i+1}\n"
    trans_content += f"{para_text}\n\n"
    trans_content += f"【白话】{trans}\n\n"
    trans_content += f"【译注】{note_text}\n\n---\n\n"

with open(trans_draft_path, "w", encoding="utf-8") as f:
    f.write(trans_content)
print(f"✅ 白话初稿写入完成: {trans_draft_path}")
